import 'package:drift/drift.dart';
import 'package:drift_flutter/drift_flutter.dart';

import 'tables.dart';

// Generated by build_runner. It holds the base class _$AppDatabase and the
// table accessors (accounts, transactions, ...). If it is missing or stale,
// every table name below shows as "undefined" in the editor.
part 'app_database.g.dart';

/// One line of the transaction list: a transaction plus the NAMES of its
/// account and category.
///
/// Why our own class: the list screen needs names, not ids, and these live in
/// other tables. We join the tables once here, so the screen stays simple.
class TxnRow {
  const TxnRow({
    required this.id,
    required this.amountKobo,
    required this.kind,
    required this.narration,
    required this.occurredAt,
    required this.accountName,
    this.categoryName,
  });

  final int id;
  final int amountKobo; // Signed: credits positive, debits negative.
  final TxnKind kind;
  final String narration;
  final DateTime occurredAt;
  final String accountName;
  final String? categoryName; // Null when the transaction has no category.
}

@DriftDatabase(
  tables: [Accounts, Categories, RawMessages, Transactions, Budgets],
)
class AppDatabase extends _$AppDatabase {
  // driftDatabase() picks the right place to store the SQLite file on each
  // platform, so we do not have to write that ourselves.
  AppDatabase() : super(driftDatabase(name: 'finance_tracker'));

  // Bump this whenever you change a table, and add a migration step below.
  @override
  int get schemaVersion => 1;

  @override
  MigrationStrategy get migration => MigrationStrategy(
    onCreate: (m) async {
      // Runs once, on first launch: create all the tables.
      await m.createAll();

      // Starting categories, so budgets and reports have something to
      // attach to. A batch sends all inserts in one go (faster).
      await batch((b) {
        b.insertAll(categories, [
          // Income
          CategoriesCompanion.insert(name: 'Salary', kind: TxnKind.income),
          CategoriesCompanion.insert(name: 'Business', kind: TxnKind.income),
          CategoriesCompanion.insert(name: 'Gifts', kind: TxnKind.income),
          CategoriesCompanion.insert(
            name: 'Other income',
            kind: TxnKind.income,
          ),
          // Expenses
          CategoriesCompanion.insert(name: 'Food', kind: TxnKind.expense),
          CategoriesCompanion.insert(name: 'Transport', kind: TxnKind.expense),
          CategoriesCompanion.insert(
            name: 'Airtime & data',
            kind: TxnKind.expense,
          ),
          CategoriesCompanion.insert(
            name: 'Bills & utilities',
            kind: TxnKind.expense,
          ),
          CategoriesCompanion.insert(name: 'Shopping', kind: TxnKind.expense),
          CategoriesCompanion.insert(
            name: 'Entertainment',
            kind: TxnKind.expense,
          ),
          CategoriesCompanion.insert(
            name: 'Bank charges',
            kind: TxnKind.expense,
          ),
          CategoriesCompanion.insert(
            name: 'Other expenses',
            kind: TxnKind.expense,
          ),
        ]);
      });
    },
    beforeOpen: (details) async {
      // SQLite ignores foreign keys unless switched on. Without this the
      // "cascade" and "set null" rules in tables.dart do nothing.
      await customStatement('PRAGMA foreign_keys = ON');
    },
  );

  // -------------------------------------------------------------------------
  // ACCOUNTS
  // -------------------------------------------------------------------------

  /// A live list of accounts. "watch" means the screen rebuilds by itself
  /// whenever an account is added or changed, with no manual refresh code.
  Stream<List<Account>> watchAccounts() {
    return (select(accounts)
          // Archived accounts are hidden, not deleted, so history is kept.
          ..where((a) => a.archived.equals(false))
          ..orderBy([(a) => OrderingTerm.asc(a.id)]))
        .watch();
  }

  /// The same list, read once (used by forms that only need it on open).
  Future<List<Account>> getAccounts() {
    return (select(accounts)
          ..where((a) => a.archived.equals(false))
          ..orderBy([(a) => OrderingTerm.asc(a.id)]))
        .get();
  }

  /// Creates an account. [openingBalanceKobo] is what the account held when
  /// you started tracking it. Every later change comes from transactions.
  Future<int> addAccount({
    required String name,
    required AccountType type,
    required int openingBalanceKobo,
  }) {
    return into(accounts).insert(
      AccountsCompanion.insert(
        name: name,
        type: type,
        openingBalanceKobo: Value(openingBalanceKobo),
      ),
    );
  }

  // -------------------------------------------------------------------------
  // CATEGORIES
  // -------------------------------------------------------------------------

  /// Categories of one kind (income or expense), sorted A to Z, so the form
  /// only offers categories that make sense for what you are adding.
  Future<List<Category>> getCategories(TxnKind kind) {
    return (select(categories)
          ..where((c) => c.kind.equalsValue(kind))
          ..orderBy([(c) => OrderingTerm.asc(c.name)]))
        .get();
  }

  // -------------------------------------------------------------------------
  // TRANSACTIONS
  // -------------------------------------------------------------------------

  /// A live list of all transactions, newest first, with account and category
  /// names filled in.
  Stream<List<TxnRow>> watchTransactions() {
    // join() combines tables. innerJoin keeps only rows that have a match
    // (every transaction has an account). leftOuterJoin keeps the
    // transaction even when it has NO category.
    final query =
        select(transactions).join([
          innerJoin(accounts, accounts.id.equalsExp(transactions.accountId)),
          leftOuterJoin(
            categories,
            categories.id.equalsExp(transactions.categoryId),
          ),
        ])..orderBy([
          OrderingTerm.desc(transactions.occurredAt),
          // Tie-breaker so two entries at the same minute keep a stable order.
          OrderingTerm.desc(transactions.id),
        ]);

    return query.watch().map((rows) {
      return rows.map((row) {
        final t = row.readTable(transactions);
        final a = row.readTable(accounts);
        // readTableOrNull because the category side may be missing.
        final c = row.readTableOrNull(categories);
        return TxnRow(
          id: t.id,
          amountKobo: t.amountKobo,
          kind: t.kind,
          narration: t.narration,
          occurredAt: t.occurredAt,
          accountName: a.name,
          categoryName: c?.name,
        );
      }).toList();
    });
  }

  /// Saves a manual transaction. Pass [amountKobo] as a POSITIVE number; this
  /// method applies the sign (expenses are stored negative, income positive).
  /// That way the form cannot save a wrong sign by mistake.
  Future<int> addTransaction({
    required int accountId,
    int? categoryId,
    required int amountKobo,
    required TxnKind kind,
    required DateTime occurredAt,
    String narration = '',
  }) {
    final signed = kind == TxnKind.expense
        ? -amountKobo.abs()
        : amountKobo.abs();

    return into(transactions).insert(
      TransactionsCompanion.insert(
        accountId: accountId,
        categoryId: Value(categoryId),
        amountKobo: signed,
        kind: kind,
        occurredAt: occurredAt,
        narration: Value(narration),
        source: const Value(TxnSource.manual),
      ),
    );
  }

  /// Permanently removes one transaction.
  Future<void> deleteTransaction(int id) {
    return (delete(transactions)..where((t) => t.id.equals(id))).go();
  }

  // -------------------------------------------------------------------------
  // BALANCE AND MONTHLY SUMMARY (kept for later screens such as budgets)
  // -------------------------------------------------------------------------

  /// Current balance of one account in kobo:
  /// opening balance + the sum of all its transactions.
  Future<int> currentBalanceKobo(int accountId) async {
    final account = await (select(
      accounts,
    )..where((a) => a.id.equals(accountId))).getSingle();

    // Ask SQLite to add everything up itself: much faster than loading every
    // row into Dart.
    final total = transactions.amountKobo.sum();
    final row =
        await (selectOnly(transactions)
              ..addColumns([total])
              ..where(transactions.accountId.equals(accountId)))
            .getSingle();

    // SUM over zero rows returns null, so treat that as 0.
    return account.openingBalanceKobo + (row.read(total) ?? 0);
  }

  /// Total income and expenses for a month, in kobo. Transfers are excluded
  /// on purpose. Expenses come back as a positive number.
  Future<({int income, int expense})> monthlyTotals(int year, int month) async {
    final start = DateTime(year, month);
    // DateTime rolls month 13 over into January of next year for us.
    final end = DateTime(year, month + 1);

    Future<int> sumFor(TxnKind kind) async {
      final total = transactions.amountKobo.sum();
      final row =
          await (selectOnly(transactions)
                ..addColumns([total])
                ..where(
                  transactions.kind.equalsValue(kind) &
                      transactions.occurredAt.isBiggerOrEqualValue(start) &
                      transactions.occurredAt.isSmallerThanValue(end),
                ))
              .getSingle();
      return row.read(total) ?? 0;
    }

    final income = await sumFor(TxnKind.income);
    final expense = await sumFor(TxnKind.expense);
    return (income: income, expense: -expense);
  }
}
